-- 6.2.a Determine whether a producer's metric is going up or down over time
-- Requirement: SELECT, LAG(), PARTITION BY, ORDER BY, LEAD()

SELECT
    trip_id,
    driver_id,
    requested_at,
    fare_amount,

    LAG(fare_amount) OVER (
        PARTITION BY driver_id
        ORDER BY requested_at
    ) AS previous_fare,

    LEAD(fare_amount) OVER (
        PARTITION BY driver_id
        ORDER BY requested_at
    ) AS next_fare,

    fare_amount - LAG(fare_amount) OVER (
        PARTITION BY driver_id
        ORDER BY requested_at
    ) AS fare_change

FROM trips
WHERE driver_id = 1
ORDER BY requested_at;

