-- 6.2.b Platform performance over time. Determine performance based on both the total and recent average.
-- Requirement: SELECT, SUM, ORDER BY, ROWS BETWEEN UNBOUNDED PRECEDING

SELECT
    trip_id,
    requested_at,
    fare_amount,

    SUM(fare_amount) OVER (
        ORDER BY requested_at, trip_id
        ROWS BETWEEN UNBOUNDED PRECEDING
        AND CURRENT ROW
    ) AS running_total,

    AVG(fare_amount) OVER (
        ORDER BY requested_at, trip_id
        ROWS BETWEEN 6 PRECEDING
        AND CURRENT ROW
    ) AS moving_average,

    4000.00 AS fare_target,

    4000.00 - SUM(fare_amount) OVER (
        ORDER BY requested_at, trip_id
        ROWS BETWEEN UNBOUNDED PRECEDING
        AND CURRENT ROW
    ) AS target_amount_remaining

FROM trips
ORDER BY requested_at, trip_id;

