-- 6.2.c Determine the gaps for when a producer stops for a while and starts again
-- Requirement: SELECT, AVG, OVER, PARTITION BY, ORDER BY, GROUP BY

WITH driver_gaps AS (
    SELECT
        driver_id,
        trip_id,
        requested_at,

        LAG(requested_at) OVER (
            PARTITION BY driver_id
            ORDER BY requested_at
        ) AS previous_trip_at

    FROM trips
    WHERE driver_id = 1
)

SELECT
    driver_id,
    previous_trip_at,
    requested_at AS next_trip_at,
    requested_at - previous_trip_at AS time_between_trips

FROM driver_gaps
WHERE requested_at - previous_trip_at > INTERVAL '30 days'
ORDER BY requested_at;

